public boolean mergeTriplets(int[][] triplets, int[] target) {
    int n = triplets.length;
    for (int mask = 1; mask < (1 << n); mask++) {
        int a = 0, b = 0, c = 0;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) {
                a = Math.max(a, triplets[i][0]);
                b = Math.max(b, triplets[i][1]);
                c = Math.max(c, triplets[i][2]);
            }
        }
        if (a == target[0] && b == target[1] && c == target[2]) return true;
    }
    return false;
}

code.python:
def mergeTriplets(self, triplets: list[list[int]], target: list[int]) -> bool:
    n = len(triplets)
    for mask in range(1, 1 << n):
        a = b = c = 0
        for i in range(n):
            if mask & (1 << i):
                a = max(a, triplets[i][0])
                b = max(b, triplets[i][1])
                c = max(c, triplets[i][2])
        if [a, b, c] == target:
            return True
    return False

code.java:
public boolean mergeTriplets(int[][] triplets, int[] target) {
    boolean[] hit = new boolean[3];
    for (int[] t : triplets) {
        if (t[0] <= target[0] && t[1] <= target[1] && t[2] <= target[2]) {
            for (int k = 0; k < 3; k++) {
                if (t[k] == target[k]) hit[k] = true;
            }
        }
    }
    return hit[0] && hit[1] && hit[2];
}

code.python:
def mergeTriplets(self, triplets: list[list[int]], target: list[int]) -> bool:
    hit = [False, False, False]
    for t in triplets:
        if t[0] <= target[0] and t[1] <= target[1] and t[2] <= target[2]:
            for k in range(3):
                if t[k] == target[k]:
                    hit[k] = True
    return all(hit)

